   import React, { useState, useEffect } from 'react';
   import api from '@landinghub/api';  // Axios instance

   const Leads = () => {
     const [leads, setLeads] = useState([]);
     const [loading, setLoading] = useState(true);
     const [error, setError] = useState(null);

     // Mock data tạm nếu API fail (xóa khi backend OK)
     const mockLeads = [
       { _id: '1', name: 'Test User', email: 'test@example.com', phone: '0123456789', status: 'new', notes: '' },
       { _id: '2', name: 'User  2', email: 'user2@example.com', phone: '0987654321', status: 'processing', notes: 'Ghi chú test' }
     ];

     // Lấy danh sách leads từ API (sử dụng endpoint trực tiếp)
     const fetchLeads = async () => {
       setLoading(true);
       setError(null);
       try {
         console.log('Calling API: GET /leads');  // Log debug
         const response = await api.get('/leads');  // Thay vì api.getLeads()
         console.log('API Response:', response.data);  // Log data
         setLeads(response.data || []);  // Giả sử response.data là array
       } catch (err) {
         console.error('API Error Details:', err.response?.data || err.message);
         setError(`Lấy dữ liệu leads thất bại: ${err.response?.status || err.message}`);
         // Mock data để test UI
         setLeads(mockLeads);
       } finally {
         setLoading(false);
       }
     };

     useEffect(() => {
       fetchLeads();
     }, []);

     // Cập nhật lead (PUT /leads/:id)
     const updateLead = async (id, field, value) => {
       try {
         await api.put(`/leads/${id}`, { [field]: value });  // Endpoint PUT
         setLeads(prev =>
           prev.map(lead => (lead._id === id ? { ...lead, [field]: value } : lead))
         );
       } catch (err) {
         alert(`Cập nhật thất bại: ${err.message}`);
       }
     };

     // Xóa lead (DELETE /leads/:id)
     const deleteLead = async (id) => {
       if (!window.confirm('Xóa lead?')) return;
       try {
         await api.delete(`/leads/${id}`);  // Endpoint DELETE
         setLeads(prev => prev.filter(lead => lead._id !== id));
       } catch (err) {
         alert(`Xóa thất bại: ${err.message}`);
       }
     };

     const retryFetch = () => fetchLeads();

     if (loading) return <p>Đang tải...</p>;

     return (
       <div>
         <h2>Quản lý Leads</h2>
         {error && (
           <div style={{ color: 'red', marginBottom: '10px' }}>
             {error}
             <button onClick={retryFetch} style={{ marginLeft: '10px' }}>Thử lại</button>
           </div>
         )}
         <table border="1" cellPadding="8" cellSpacing="0" style={{ width: '100%', borderCollapse: 'collapse' }}>
           <thead>
             <tr>
               <th>Tên</th>
               <th>Email</th>
               <th>Điện thoại</th>
               <th>Trạng thái</th>
               <th>Ghi chú</th>
               <th>Hành động</th>
             </tr>
           </thead>
           <tbody>
             {leads.length === 0 ? (
               <tr>
                 <td colSpan="6" style={{ textAlign: 'center' }}>Chưa có lead</td>
               </tr>
             ) : (
               leads.map(lead => (
                 <tr key={lead._id}>
                   <td>{lead.name}</td>
                   <td>{lead.email}</td>
                   <td>{lead.phone}</td>
                   <td>
                     <select value={lead.status} onChange={e => updateLead(lead._id, 'status', e.target.value)}>
                       <option value="new">Mới</option>
                       <option value="processing">Đang xử lý</option>
                       <option value="converted">Chuyển đổi</option>
                       <option value="lost">Mất</option>
                     </select>
                   </td>
                   <td>
                     <input
                       type="text"
                       value={lead.notes || ''}
                       onChange={e => updateLead(lead._id, 'notes', e.target.value)}
                       placeholder="Ghi chú"
                       style={{ width: '100%' }}
                     />
                   </td>
                   <td>
                     <button onClick={() => deleteLead(lead._id)} style={{ color: 'red' }}>Xóa</button>
                   </td>
                 </tr>
               ))
             )}
           </tbody>
         </table>
       </div>
     );
   };

   export default React.memo(Leads);
